using Microsoft.Extensions.AI;

public class SlidingContextManager
{
    private readonly int _maxAllowedTokens;

    public SlidingContextManager(int maxAllowedTokens = 4000)
    {
        _maxAllowedTokens = maxAllowedTokens;
    }

    public List<ChatMessage> PruneHistory(List<ChatMessage> fullHistory)
    {
        var systemMsg = fullHistory.FirstOrDefault(m => m.Role == ChatRole.System);
        var conversation = fullHistory.Where(m => m.Role != ChatRole.System).ToList();

        var pruned = new List<ChatMessage>();
        int currentTokens = systemMsg != null ? EstimateTokens(systemMsg.Text ?? "") : 0;

        // Walk backwards from newest message to oldest
        for (int i = conversation.Count - 1; i >= 0; i--)
        {
            var msgTokens = EstimateTokens(conversation[i].Text ?? "");
            if (currentTokens + msgTokens > _maxAllowedTokens)
            {
                break; // Stop taking older messages
            }

            pruned.Insert(0, conversation[i]);
            currentTokens += msgTokens;
        }

        if (systemMsg != null)
        {
            pruned.Insert(0, systemMsg);
        }

        return pruned;
    }

    private static int EstimateTokens(string text) => (int)Math.Ceiling(text.Length / 4.0);
}
